DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('system_integrity_private.scan_system_red_flags()'::regprocedure) INTO definition; definition:=replace(definition,'was_resolved boolean;','was_resolved boolean; candidates jsonb;'); definition:=replace(definition,'CREATE TEMP TABLE IF NOT EXISTS current_red_flags (fingerprint text,rule_key text,department text,severity text,title text,details jsonb,review_path text) ON COMMIT DROP; TRUNCATE pg_temp.current_red_flags; INSERT INTO pg_temp.current_red_flags SELECT * FROM public.system_red_flag_candidates; FOR c IN SELECT * FROM pg_temp.current_red_flags LOOP','SELECT coalesce(jsonb_agg(to_jsonb(candidate)),''[]''::jsonb) INTO candidates FROM public.system_red_flag_candidates candidate; FOR c IN SELECT * FROM jsonb_to_recordset(candidates) AS issue(fingerprint text,rule_key text,department text,severity text,title text,details jsonb,review_path text) LOOP'); definition:=replace(definition,'SELECT 1 FROM pg_temp.current_red_flags candidate WHERE candidate.fingerprint=f.fingerprint','SELECT 1 FROM jsonb_array_elements(candidates) candidate WHERE candidate->>''fingerprint''=f.fingerprint'); EXECUTE definition; END; $$;